parameters.jsCode:
const promptVersion = 'b11-response-v1';
// B11 Review Pro — Parser
const rawText = $input.item.json['rawAIText'] || '';

// Edit Fields1 (Set v3.4, options:{}) drops upstream fields — re-fetch from whichever Edit Fields node fired
function getUpstream(name) {
  try { return $(name).item.json; } catch (e) { return null; }
}
const ec = getUpstream('Edit Fields — E-Commerce');
const ai = getUpstream('Edit Fields — Airbnb');
const src = ec || ai || {};

const cleaned = rawText.replace(/```json/g, '').replace(/```/g, '').trim();
let parsed;
try { parsed = JSON.parse(cleaned); }
catch (e) {
  const m = cleaned.match(/\{[\s\S]*\}/);
  if (m) { try { parsed = JSON.parse(m[0]); } catch (e2) { parsed = null; } }
}

const rating = parseInt(src['starRating']) || 5;
let defaultPriority = 'Low';
if (rating <= 2) defaultPriority = 'High';
else if (rating === 3) defaultPriority = 'Medium';

if (!parsed || !parsed['response']) {
  parsed = {
    response: 'Thank you for your feedback. We appreciate you taking the time to share your experience and will be in touch.',
    tone: 'Fallback',
    priority: defaultPriority
  };
}
const parseSuccess = parsed['tone'] !== 'Fallback';

const priority = parsed['priority'] || defaultPriority;
const priorityColor = priority === 'High' ? '#f43f5e' : (priority === 'Medium' ? '#f59e0b' : '#10b981');
const priorityEmoji = priority === 'High' ? '🚨' : (priority === 'Medium' ? '⚠️' : '✅');

const stars = '★'.repeat(rating) + '☆'.repeat(5 - rating);

return {
  channel: src['channel'] || 'unknown',
  businessName: src['businessName'] || src['propertyName'] || 'Unknown',
  propertyName: src['propertyName'] || '',
  reviewerName: src['reviewerName'] || '',
  guestName: src['guestName'] || '',
  reviewText: src['reviewText'] || '',
  ownerEmail: src['ownerEmail'] || 'ndumisoseth12@gmail.com',
  starRating: src['starRating'] || rating,
  source: src['source'] || 'unknown',
  requestedTone: src['tone'] || '',
  context: src['context'] || '',
  promptVersion,
  aiResponse: parsed['response'],
  tone: parsed['tone'] || 'Warm',
  priority,
  priorityColor,
  priorityEmoji,
  stars,
  rating,
  parseSuccess,
  loggedAt: $now.setZone('Africa/Johannesburg').toFormat('yyyy-MM-dd HH:mm:ss'),
  loggedAtSAST: $now.setZone('Africa/Johannesburg').toFormat('yyyy-MM-dd HH:mm:ss')
};

