const promptVersion = 'b11-request-v1';
// B11 Review Request — Parser
const rawText = $input.item.json['rawAIText'] || '';
const d = $('Edit Fields — Request').item.json;
const cleaned = rawText.replace(/```json/g, '').replace(/```/g, '').trim();
let parsed;
try { parsed = JSON.parse(cleaned); }
catch (e) {
  const m = cleaned.match(/\{[\s\S]*\}/);
  if (m) { try { parsed = JSON.parse(m[0]); } catch (e2) { parsed = null; } }
}
const aiSucceeded = !!(parsed && parsed['body'] && parsed['subject']);
if (!aiSucceeded) {
  parsed = {
    subject: 'Quick favour from ' + d['businessName'],
    body: 'Hi ' + d['firstName'] + ', thank you for choosing ' + d['businessName'] + '. If you have a moment, we would really appreciate a quick review on ' + d['platform'] + '. It helps us a lot. Thanks again, ' + d['clientName']
  };
}
return { ...d, promptVersion, subject: parsed['subject'], body: parsed['body'], parseSuccess: aiSucceeded };

